import '../../../core/network/api_client.dart';import 'models/auth_session_model.dart';
class AuthApiDatasource{AuthApiDatasource(this.client);final ApiClient client;Future<Map<String,dynamic>> register(Map<String,dynamic> d)async=>(await client.dio.post('/auth/register',data:d)).data['data'];Future<AuthSessionModel> login(String p,String pw)async=>AuthSessionModel.fromJson((await client.dio.post('/auth/login',data:{'phone':p,'password':pw})).data['data']);Future<AuthSessionModel> verify(String p,String o)async=>AuthSessionModel.fromJson((await client.dio.post('/auth/verify',data:{'phone':p,'otp':o})).data['data']);Future<void> logout()async{await client.dio.post('/auth/logout');}Future<void> forgot(String p)async{await client.dio.post('/auth/password/forgot',data:{'phone':p});}Future<void> reset(String p,String o,String pw)async{await client.dio.post('/auth/password/reset',data:{'phone':p,'otp':o,'password':pw,'password_confirmation':pw});}}
